<article class="library-card">@if($resource->cover_url)<img src="{{ $resource->cover_url }}" alt="{{ $resource->title }}">@else<div class="library-cover-placeholder">RHMI</div>@endif<div class="library-card-body"><p class="library-meta">{{ $resource->category?->name ?: \App\Models\LibraryResource::TYPES[$resource->resource_type] }}</p><h3>{{ $resource->title }}</h3>@if($resource->author)<p class="library-author">By {{ $resource->author }}</p>@endif<p>{{ \Illuminate\Support\Str::limit($resource->description,120) }}</p><div class="library-card-footer"><strong>{{ $resource->is_paid ? 'UGX '.number_format($resource->price_ugx) : 'Free' }}</strong><a href="{{ route('library.show',$resource) }}" class="btn btn-outline">View Resource</a></div></div></article>
